#!/usr/bin/env bash
# Pre-populates the live dl1.sales_data table over Quack with the seed data
# generated by generate_sales_data.py. Requires the SSH tunnel to be running
# (./scripts/start_ssh_tunnel.sh) and the tunnel's local port to match.
set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
terraform_dir="$(cd "$script_dir/../terraform" && pwd)"
sample_dir="$(cd "$script_dir/.." && pwd)/sample_data"
insert_sql_file="$sample_dir/seed_insert.sql"

if [[ ! -f "$insert_sql_file" ]]; then
  echo "Missing $insert_sql_file. Run: python scripts/generate_sales_data.py"
  exit 1
fi

if ! command -v duckdb >/dev/null 2>&1; then
  echo "duckdb CLI is required (brew install duckdb)."
  exit 1
fi

quack_token="$(terraform -chdir="$terraform_dir" output -raw quack_token)"
local_port="${LOCAL_PORT:-9494}"

# The generated INSERT is one big multi-row statement; escape single quotes
# so it can be embedded as a string literal inside remote.query('...').
insert_sql_escaped="$(sed "s/'/''/g" "$insert_sql_file")"

duckdb :memory: <<SQL
INSTALL quack; LOAD quack;
ATTACH 'quack:localhost:${local_port}' AS remote (TOKEN '${quack_token}');
FROM remote.query('${insert_sql_escaped}');
FROM remote.query('SELECT region_name, count(*) AS rows FROM dl1.sales_data GROUP BY region_name ORDER BY region_name');
SQL
